def weighted_distance_sums(n: int, edges: list[list[int]], w: list[int]) -> list[int]:
    if n == 1:
        return [0]
    g = [[] for _ in range(n)]
    for a, b in edges:
        g[a].append(b)
        g[b].append(a)
    sub_w = [0] * n
    parent = [-1] * n
    order = []
    stack = [0]
    parent[0] = -2
    while stack:
        u = stack.pop()
        order.append(u)
        for v in g[u]:
            if parent[v] == -1:
                parent[v] = u
                stack.append(v)
    for u in reversed(order):
        sw = w[u]
        ss = 0
        for v in g[u]:
            if v != parent[u]:
                sw += sub_w[v]
                ss += sub_s[v] + sub_w[v]
        sub_w[u] = sw
        sub_s[u] = ss
    total = sub_w[0]
    ans = [0] * n
    ans[0] = sub_s[0]
    for u in order:
        for v in g[u]:
            if v != parent[u]:
                ans[v] = ans[u] + total - 2 * sub_w[v]
    return ans
